('faq_json', '[{"q":"Что входит в комплект арки?","a":"Каркас арки и крепёж: болты, шайбы, гайки. Обшивку и фундамент подбираете отдельно или обсуждаем комплектацию."},{"q":"Какой фундамент нужен?","a":"Можно ставить на обвязку, спецблоки, плиту, заливные или винтовые сваи. Капитальный фундамент для стандартных арок не обязателен."},{"q":"С какой нагрузкой рассчитаны арки?","a":"В зависимости от серии — ориентировочно 180–200 кг/м². Точные параметры уточняем по выбранной ширине."},{"q":"Какой шаг установки арок?","a":"Типовой шаг — 3 метра. Длину объекта набираете нужным количеством секций."},{"q":"Доставляете по России?","a":"Да, выгодная доставка по РФ. Стоимость и сроки считаем по адресу и объёму заказа."},{"q":"Сложно ли собрать каркас?","a":"Конструкция сборно-разборная на болтовом соединении — быстрое и простое возведение без сварки на объекте."}]'),
