INSERT INTO pages_seo (page_key, title, description, h1, og_title, og_description, robots) VALUES
('home', 'МеталлКомплект31 — сборные металлоконструкции', 'Арочные каркасы и хозблоки на болтовом соединении. Гараж, ангар, склад, навес. Доставка по РФ. Цены от 17 000 ₽.', 'Сборные металлоконструкции с доставкой по РФ', 'МеталлКомплект31 — сборные металлоконструкции', 'Быстровозводимые арки и каркасы на краб-системе. Болтовое соединение, монтаж без сварки.', 'index,follow'),
('privacy', 'Политика конфиденциальности — МеталлКомплект31', 'Политика обработки персональных данных сайта МеталлКомплект31.', 'Политика конфиденциальности', 'Политика конфиденциальности', 'Как обрабатываются персональные данные с формы заявки.', 'index,follow'),
('offer', 'Публичная оферта — МеталлКомплект31', 'Публичная оферта на поставку металлоконструкций МеталлКомплект31.', 'Публичная оферта', 'Публичная оферта', 'Условия поставки металлоконструкций и подачи заявок.', 'index,follow')
INSERT INTO services (slug, title, short_text, full_text, price_from, price_note, period, icon, sort_order, is_active, is_featured, cta_label) VALUES
('arch-3m', 'Арка ширина 3 м', 'Высота по стене 2,3 м, в коньке 3,2 м. Нагрузка до 190 кг/м², шаг 3 м.', 'Комплект арки с болтами, шайбами и гайками. Установка на обвязку, спецблоки, плиту или сваи. Доставка по РФ.', 19000.00, 'за арку', 'one_time', 'A', 10, 1, 1, 'Заказать арку 3 м'),
('arch-4m', 'Арка ширина 4 м', 'Высота по стене 2,3 м, в коньке 3,2 м. Нагрузка до 190 кг/м², шаг 3 м.', 'Болтовое соединение, сборно-разборный каркас. Подходит для гаража и навеса.', 20000.00, 'за арку', 'one_time', 'A', 20, 1, 1, 'Заказать арку 4 м'),
('arch-5m', 'Арка ширина 5 м', 'Высота по стене 2,3 м, в коньке 3,5 м. Нагрузка до 180 кг/м².', 'Не требует капитального фундамента. Монтаж на обвязку, блоки, плиту или сваи.', 22000.00, 'за арку', 'one_time', 'A', 30, 1, 0, 'Заказать арку 5 м'),
('arch-6m', 'Арка ширина 6 м', 'Высота по стене 2,3 м, в коньке 3,7 м. Нагрузка до 180 кг/м², шаг 3 м.', 'Оптимальный размер для ангара и склада. Крепёж в комплекте.', 23000.00, 'за арку', 'one_time', 'A', 40, 1, 1, 'Заказать арку 6 м'),
('arch-4m-tall', 'Арка 4 м усиленная', 'Внутри 4 м, снаружи 4,7 м. Высота 2,8–3,6 м. Нагрузка до 190 кг/м².', 'Фундамент: заливные/винтовые сваи или плита. Крепёж в комплекте.', 29000.00, 'за арку', 'one_time', 'A', 50, 1, 0, 'Заказать'),
('arch-6m-tall', 'Арка 6 м высокая', 'Высота в нижней точке 2,5 м, в верхней 3,9 м. Нагрузка до 190 кг/м².', 'Усиленная серия для ангаров. Шаг арок 3 м, крепёж в комплекте.', 35000.00, 'за арку', 'one_time', 'A', 60, 1, 1, 'Заказать'),
('arch-6m-pillars', 'Арка 6 м со столбами', 'Столбы из трубы 80×80. Высота по стене 2,9 м, в коньке 4,2 м. До 200 кг/м².', 'Повышенная жёсткость. Фундамент: сваи или плита.', 34000.00, 'за арку', 'one_time', 'A', 70, 1, 0, 'Заказать'),
('arch-8m', 'Арка ширина 8 м', 'Столбы из трубы 120×80. Высота по стене 4,4 м, в коньке 5,3 м. До 200 кг/м².', 'Крупный пролёт для склада и ангара. Шаг 3 м, крепёж в комплекте.', 44000.00, 'за арку', 'one_time', 'A', 80, 1, 1, 'Заказать арку 8 м'),
('arch-6m-high', 'Арка высокая 6 м', 'Высота по стене 4,6 м, в коньке 6,1 м. Нагрузка до 200 кг/м².', 'Высокая серия для техники и складских объёмов. Болтовой крепёж в комплекте.', 39000.00, 'за арку', 'one_time', 'A', 90, 1, 0, 'Заказать'),
('arch-8m-alt', 'Арка 8 м (высокая серия)', 'Широкий пролёт 8 м для крупных объектов. Нагрузка до 200 кг/м², шаг 3 м.', 'Крепёж в комплекте. Подбор фундамента и доставки — по заявке.', 43000.00, 'за арку', 'one_time', 'A', 100, 1, 0, 'Заказать'),
('frame-hozblok', 'Каркас хозблока (краб-система)', 'Универсальный сборный каркас 3×2 … 6×2 м. В комплекте крабы, болты, саморезы, пластины, обвязка.', 'Размерный ряд: 3×2 — 35 000 ₽, 4×2 — 39 000 ₽, 5×2 — 44 000 ₽, 6×2 — 48 000 ₽.', 35000.00, 'от размера', 'one_time', 'K', 110, 1, 1, 'Заказать каркас'),
('frame-shower', 'Каркас душа / санузла / кладовки', 'Компактный каркас 840×1150 мм на краб-системе. Крепёж в комплекте.', 'Краб-системы, болты, саморезы, пластины, обвязка — всё для сборки.', 17000.00, 'за каркас', 'one_time', 'K', 120, 1, 0, 'Заказать'),
('delivery-rf', 'Доставка по РФ', 'Выгодная доставка комплектов по всей России. Срок и цена — по адресу.', 'Рассчитаем стоимость доставки после уточнения населённого пункта и объёма заказа.', NULL, 'по запросу', 'custom', 'D', 130, 1, 0, 'Рассчитать доставку');
